import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface ManufacturerDto { id?: number | null; name: string; }
export interface CarDto { id?: number | null; model: string; manufacturer?: ManufacturerDto | null; }
export interface RatingDto { id?: number | null; rating: number | null; car: CarDto | null; }
export interface ManufacturerRatingDto { manufacturer: string; rating: number; }

export function carLabel(car: CarDto | null | undefined): string {
  if (car && car.manufacturer) { return car.manufacturer.name + '/' + car.model; }
  return '';
}
export function ratingLabel(r: RatingDto): string {
  return r.car && r.car.manufacturer ? carLabel(r.car) : String(r.id ?? '');
}

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  getManufacturers(): Observable<ManufacturerDto[]> { return this.http.get<ManufacturerDto[]>('/api/manufacturers'); }
  saveManufacturer(m: ManufacturerDto): Observable<ManufacturerDto> { return this.http.post<ManufacturerDto>('/api/manufacturers', m); }
  deleteManufacturer(id: number): Observable<void> { return this.http.delete<void>('/api/manufacturers/' + id); }
  getAverageRatings(): Observable<ManufacturerRatingDto[]> { return this.http.get<ManufacturerRatingDto[]>('/api/manufacturers/ratings'); }
  getRatings(): Observable<RatingDto[]> { return this.http.get<RatingDto[]>('/api/ratings'); }
  saveRating(r: RatingDto): Observable<RatingDto> { return this.http.post<RatingDto>('/api/ratings', r); }
  deleteRating(id: number): Observable<void> { return this.http.delete<void>('/api/ratings/' + id); }
  getCars(): Observable<CarDto[]> { return this.http.get<CarDto[]>('/api/cars', { params: { offset: 0, limit: -1 } }); }
}
