import { Component, OnInit, inject } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ApiService, CarDto, RatingDto, carLabel, ratingLabel } from './api.service';
import { MessageService } from './message.service';

@Component({
  selector: 'app-rating',
  standalone: true,
  imports: [FormsModule],
  template: `
    <div class="bigTitle">
      <h2>Ratings</h2>
      <button id="gwt-debug-ratingCreate" class="addAction" (click)="create()">Create</button>
    </div>
    <table id="gwt-debug-ratings" class="grid">
      <thead><tr><th>ID</th><th>Car</th><th>Rating</th><th>Delete</th></tr></thead>
      <tbody>
        @for (r of items; track r.id) {
          <tr>
            <td>{{ r.id }}</td><td>{{ label(r) }}</td><td>{{ r.rating }}</td>
            <td><button (click)="remove(r)">Delete</button></td>
          </tr>
        }
      </tbody>
    </table>
    @if (editing) {
      <div class="glass"></div>
      <div class="popup">
        <div><span>Car:</span>
          <select [(ngModel)]="editing.car">
            @for (c of cars; track c.id) { <option [ngValue]="c">{{ carLabel(c) }}</option> }
          </select>
        </div>
        <div><span>Your rating:</span>
          <input id="gwt-debug-ratingInput" type="number" maxlength="3" [(ngModel)]="editing.rating">
        </div>
        <div>
          <button id="gwt-debug-ratingSave" (click)="save()">Save</button>
          <button (click)="close()">Close</button>
        </div>
      </div>
    }`,
})
export class RatingComponent implements OnInit {
  private api = inject(ApiService);
  private msg = inject(MessageService);
  items: RatingDto[] = [];
  cars: CarDto[] = [];
  editing: RatingDto | null = null;
  label = ratingLabel;
  carLabel = carLabel;

  ngOnInit(): void {
    this.api.getRatings().subscribe({ next: l => this.items = l, error: () => this.msg.error('Failed to load ratings') });
  }
  create(): void {
    this.api.getCars().subscribe({
      next: cars => {
        this.cars = cars;
        this.editing = { car: cars.length ? cars[0] : null, rating: null };
      },
      error: () => this.msg.error('Failed to load cars'),
    });
  }
  close(): void { this.editing = null; }
  save(): void {
    if (!this.editing) { return; }
    this.api.saveRating(this.editing).subscribe({
      next: saved => {
        this.items = [...this.items, saved];
        this.msg.show('Rating saved');
        this.editing = null;
      },
      error: () => this.msg.error('Failed to save rating'),
    });
  }
  remove(r: RatingDto): void {
    if (!window.confirm('Are you sure you want to delete this rating?')) { return; }
    this.api.deleteRating(r.id as number).subscribe({
      next: () => this.items = this.items.filter(x => x !== r),
      error: () => this.msg.error('Failed to delete rating'),
    });
  }
}
