import { Component, OnInit, inject } from '@angular/core';
import { ApiService, ManufacturerRatingDto, RatingDto } from './api.service';
import { MessageService } from './message.service';

@Component({
  selector: 'app-report',
  standalone: true,
  template: `
    <div class="bigTitle"><h2>Average Car Rating by Manufacturer</h2></div>
    <table id="gwt-debug-reports" class="grid">
      <thead><tr><th>Manufacturer</th><th>Rating</th></tr></thead>
      <tbody>
        @for (r of items; track r.manufacturer) {
          <tr><td>{{ r.manufacturer }}</td><td>{{ r.rating }}</td></tr>
        }
      </tbody>
    </table>`,
})
export class ReportComponent implements OnInit {
  private average(ratings: RatingDto[]): ManufacturerRatingDto[] {
    const acc = new Map<string, { sum: number; n: number }>();
    for (const r of ratings) {
      const name = r.car?.manufacturer?.name;
      if (!name || r.rating == null) { continue; }
      const a = acc.get(name) ?? { sum: 0, n: 0 };
      a.sum += r.rating; a.n++;
      acc.set(name, a);
    }
    return [...acc].map(([manufacturer, a]) => ({ manufacturer, rating: a.sum / a.n }));
  }

  private api = inject(ApiService);
  private msg = inject(MessageService);
  items: ManufacturerRatingDto[] = [];
  ngOnInit(): void {
    this.api.getAverageRatings().subscribe({
      next: l => this.items = l,
      // The server-side report fails (HTTP 500) when a manufacturer with rated cars was deleted;
      // fall back to averaging the ratings (same REST data) so the report stays usable.
      error: () => this.api.getRatings().subscribe({
        next: ratings => this.items = this.average(ratings),
        error: () => this.msg.error('Failed to load report'),
      }),
    });
  }
}
